mapper.select:
   SELECT id source_row_id,'GSA' source_code,COALESCE(gsa_record_key,CASE WHEN pmid IS NOT NULL THEN
   CONCAT('PMID:',pmid) WHEN doi IS NOT NULL THEN CONCAT('DOI:',doi) ELSE CONCAT('LOCAL_ID:',id) END)
   source_record_key,pmid,doi,title,pub_year,journal_title,authors_json,affiliation_info,grants_json,keyword_list,mesh_headings_json,gsa_accessions,bioproject_accession,cncb_banks_json,is_primary
   primary_flag FROM gsa_publication WHERE gsa_record_key IN #{v}
OR CONCAT('PMID:',pmid) IN #{v}
OR CONCAT('DOI:',doi) IN #{v}
OR CONCAT('LOCAL_ID:',id) IN
   #{v}
